INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('islamorada-tarpon-flats', 'Islamorada Tarpon Flats', 'Florida Keys, FL', 'US', 'Saltwater', '["tarpon", "bonefish", "permit", "snook"]'::jsonb, 'fishing-spot', true, 'The self-styled sport fishing capital of the world. Poll the shallow flats and bridge channels of the middle Keys for migratory tarpon, tailing bonefish and permit, with world-class offshore reef and blue water a short run away.', '{"lat": 24.9242, "lng": -80.6278}'::jsonb, '{"current": 29, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 88, "humidity": 75, "windSpeed": 12, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-12 weight fly rod or heavy spin combo", "Tarpon flies and crab patterns", "80lb fluorocarbon shock leader", "Polarized sunglasses"], "optional": ["Flats skiff and guide", "Push pole", "Live crabs or pilchards"]}'::jsonb, '["Tarpon migration (Apr-Jul)", "Moving tides on the flats", "Dawn and dusk"]'::jsonb, 'Advanced', '["Florida saltwater fishing licence required for non-residents", "Tarpon are catch-and-release only without a harvest tag", "Check current FWC size, bag and seasonal rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('venice-louisiana-redfish', 'Venice Marsh Redfish', 'Venice, LA', 'US', 'Saltwater', '["redfish", "speckled trout", "yellowfin tuna"]'::jsonb, 'duck-spot', true, 'Where the Mississippi meets the Gulf. The Venice marsh holds enormous bull redfish in the shallow ponds and cuts, while the offshore rigs a short run out produce yellowfin tuna year-round.', '{"lat": 29.2769, "lng": -89.3556}'::jsonb, '{"current": 29, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 90, "humidity": 80, "windSpeed": 10, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin combo (30lb braid)", "Gold spoons and soft plastics", "Popping cork rigs", "Fluorocarbon leader 30-40lb"], "optional": ["Bay boat or guided charter", "8-weight fly rod for sight casting", "Trolling motor"]}'::jsonb, '["Autumn bull red run (Sep-Nov)", "Falling tide in the marsh", "Calm mornings"]'::jsonb, 'Beginner', '["Louisiana recreational fishing licence required (basic plus saltwater)", "Redfish slot and bag limits apply", "Check current LDWF rules before keeping fish"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('madison-river-montana', 'Madison River', 'Ennis, MT', 'US', 'Fly Fishing', '["brown trout", "rainbow trout"]'::jsonb, 'fishing-spot', true, 'Fifty miles of classic riffle water below Quake Lake, often called the longest riffle in America. Wade or float for wild browns and rainbows with the Madison Range as a backdrop.', '{"lat": 45.4869, "lng": -111.5297}'::jsonb, '{"current": 15, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 75, "humidity": 35, "windSpeed": 10, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["5-6 weight fly rod", "Salmonfly and caddis patterns", "Chest waders", "Polarized sunglasses"], "optional": ["Drift boat or raft", "Wading staff", "Streamer box"]}'::jsonb, '["Salmonfly hatch (late Jun-Jul)", "Caddis evenings", "Autumn brown trout run"]'::jsonb, 'Intermediate', '["Montana fishing licence and conservation licence required", "Sections have wade-only and closed-water rules — check FWP", "Hoot owl restrictions may close afternoon fishing in hot weather"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('kenai-river-salmon', 'Kenai River Salmon', 'Soldotna, AK', 'US', 'Freshwater', '["king salmon", "sockeye salmon", "rainbow trout"]'::jsonb, 'duck-spot', true, 'Alaska''s most famous salmon river, glacier-fed and turquoise, producing the largest king salmon ever recorded. Sockeye run in vast numbers through summer, with trophy rainbows and dollies feeding behind them.', '{"lat": 60.5544, "lng": -150.7772}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 62, "humidity": 70, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy salmon rod (10-15kg)", "Flipping rigs and beads", "Chest waders", "Rain gear"], "optional": ["Guided drift boat", "Bear spray", "Polarized sunglasses"]}'::jsonb, '["First sockeye run (Jun)", "Second sockeye run (Jul-Aug)", "Trophy rainbows (Sep-Oct)"]'::jsonb, 'Intermediate', '["Alaska sport fishing licence required; king salmon stamp for kings", "Emergency orders frequently restrict king salmon — check ADF&G before fishing", "Bait and tackle restrictions vary by river section and season"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('montauk-striped-bass', 'Montauk Striped Bass', 'Montauk, NY', 'US', 'Saltwater', '["striped bass", "bluefish", "false albacore"]'::jsonb, 'fishing-spot', false, 'The end of Long Island, where migrating bass and blues funnel past the lighthouse rips each autumn. Fish from the rocks at Montauk Point or run the rips by boat during the legendary fall blitz.', '{"lat": 41.0715, "lng": -71.8571}'::jsonb, '{"current": 20, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 72, "humidity": 70, "windSpeed": 15, "windDirection": "NE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-11ft surf rod or heavy spin combo", "Bucktails and metal lures", "Korkers or studded boots for the rocks", "Wetsuit or waders"], "optional": ["Boat for the rips", "Headlamp for night sessions", "Stripping basket for fly"]}'::jsonb, '["Fall run (Sep-Nov)", "Night tides", "Dawn blitzes"]'::jsonb, 'Intermediate', '["New York Recreational Marine Fishing Registry required (free)", "Striped bass slot limit and season apply", "Check current NYSDEC marine regulations"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-st-clair-smallmouth', 'Lake St. Clair', 'Detroit, MI', 'US', 'Freshwater', '["smallmouth bass", "muskellunge", "walleye"]'::jsonb, 'duck-spot', false, 'Widely rated the best smallmouth bass lake in North America. Clear water over vast weed flats holds huge numbers of hard-fighting smallmouth, plus a world-class muskie fishery.', '{"lat": 42.4667, "lng": -82.6667}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 78, "humidity": 60, "windSpeed": 12, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo (10-15lb)", "Tubes, dropshots and jerkbaits", "Sounder with mapping", "Fluorocarbon leader"], "optional": ["Bass boat or kayak", "Trolling motor with spot-lock", "Large landing net for muskie"]}'::jsonb, '["Post-spawn smallmouth (Jun)", "Autumn feeding (Sep-Oct)", "Muskie trolling (Oct-Nov)"]'::jsonb, 'Beginner', '["Michigan all-species fishing licence required", "Bass and muskie seasons and size limits apply", "Border waters — check whether you are in US or Canadian water"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('laguna-madre-redfish', 'Lower Laguna Madre', 'Port Mansfield, TX', 'US', 'Saltwater', '["redfish", "speckled trout", "black drum"]'::jsonb, 'fishing-spot', false, 'A hypersaline lagoon of gin-clear shallows and seagrass, ideal for wade fishing and sight casting. Tailing redfish and trophy speckled trout over sand potholes make this a Texas classic.', '{"lat": 26.5578, "lng": -97.4258}'::jsonb, '{"current": 30, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 92, "humidity": 70, "windSpeed": 18, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo (15-20lb braid)", "Soft plastics and topwaters", "Wading belt and stingray guards", "Polarized sunglasses"], "optional": ["Shallow-draft skiff", "8-weight fly rod", "Sun hoodie and gloves"]}'::jsonb, '["Summer wade fishing at dawn", "Autumn tailing tides", "Winter trophy trout"]'::jsonb, 'Intermediate', '["Texas fishing licence with saltwater endorsement required", "Redfish and speckled trout slot and bag limits apply", "Check current TPWD rules — trout limits have changed recently"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('san-diego-offshore-tuna', 'San Diego Offshore', 'San Diego, CA', 'US', 'Saltwater', '["yellowfin tuna", "yellowtail", "dorado"]'::jsonb, 'duck-spot', false, 'The long-range sport fishing capital. Head offshore from Point Loma for bluefin and yellowfin tuna, yellowtail on the kelp paddies, and dorado in warm-water years.', '{"lat": 32.6, "lng": -117.4}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Mainly Clear", "temperature": 72, "humidity": 65, "windSpeed": 10, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or conventional outfit (40-80lb)", "Flat-fall jigs and surface irons", "Live sardines or mackerel", "Fluorocarbon leader"], "optional": ["Multi-day sport boat charter", "Fighting belt", "Seasickness tablets"]}'::jsonb, '["Tuna season (Jun-Oct)", "Yellowtail (Apr-Sep)", "Warm-water years for dorado"]'::jsonb, 'Advanced', '["California sport fishing licence with ocean enhancement validation required", "Some trips enter Mexican waters — a Mexican licence is then required", "Check current CDFW size and bag limits"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('columbia-river-chinook', 'Columbia River Buoy 10', 'Astoria, OR/WA', 'US', 'Freshwater', '["chinook salmon", "steelhead", "white sturgeon"]'::jsonb, 'fishing-spot', false, 'The lower Columbia estuary, where returning chinook and coho stack up before pushing upriver. The Buoy 10 fishery near Astoria is one of the largest salmon gatherings in the world.', '{"lat": 46.1879, "lng": -123.8313}'::jsonb, '{"current": 19, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Foggy Morning", "temperature": 68, "humidity": 85, "windSpeed": 10, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy trolling rod", "Spinners, herring and flashers", "Downrigger or diver", "Rain gear"], "optional": ["Boat with kicker motor", "Bar-crossing safety gear", "Net with large hoop"]}'::jsonb, '["Buoy 10 chinook (Aug)", "Coho (Sep)", "Spring chinook (Apr-May)"]'::jsonb, 'Intermediate', '["Oregon or Washington licence required depending on bank; both states honour a concurrent-waters rule", "Salmon and steelhead tags required; seasons open and close at short notice", "Sturgeon is largely catch-and-release — check ODFW/WDFW"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-of-the-woods-walleye', 'Lake of the Woods', 'Baudette, MN', 'US', 'Freshwater', '["walleye", "northern pike", "smallmouth bass"]'::jsonb, 'duck-spot', false, 'Fourteen thousand islands straddling the US-Canada border. Consistent walleye fishing over mud flats and reefs in summer, and a world-famous ice fishing scene once the lake locks up.', '{"lat": 49.0, "lng": -94.8667}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 75, "humidity": 60, "windSpeed": 12, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-light spin combo", "Jigs with minnows or plastics", "Spinner rigs and crawler harnesses", "Sounder"], "optional": ["Boat or resort charter", "Ice house rental (winter)", "Layered clothing"]}'::jsonb, '["Spring walleye (May-Jun)", "Autumn structure bite (Sep-Oct)", "Ice fishing (Jan-Mar)"]'::jsonb, 'Beginner', '["Minnesota fishing licence required", "Border waters — an Ontario licence is required to fish Canadian water", "Walleye bag and slot limits apply; check current MN DNR rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('bow-river-alberta', 'Bow River', 'Calgary, AB', 'CA', 'Fly Fishing', '["brown trout", "rainbow trout"]'::jsonb, 'fishing-spot', true, 'A tailwater running straight through Calgary and out into the prairie, holding exceptional numbers of wild browns and rainbows. Nutrient-rich water grows big fish in an unlikely urban setting.', '{"lat": 51.0447, "lng": -114.0719}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 72, "humidity": 45, "windSpeed": 12, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["6-weight fly rod", "Hopper and streamer patterns", "Chest waders", "Polarized sunglasses"], "optional": ["Drift boat or raft", "Wading staff", "Strike indicators"]}'::jsonb, '["Hopper season (Jul-Sep)", "Autumn streamer fishing", "Blue-winged olive hatches"]'::jsonb, 'Intermediate', '["Alberta sportfishing licence and WIN card required", "Bait bans and catch-and-release rules apply on much of the river", "Check current Alberta fishing regulations before keeping fish"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('campbell-river-bc', 'Campbell River', 'Vancouver Island, BC', 'CA', 'Saltwater', '["chinook salmon", "coho salmon", "halibut"]'::jsonb, 'duck-spot', true, 'The self-declared salmon capital of the world, sitting on Discovery Passage where tidal currents concentrate feeding chinook. Troll the tide lines for salmon or drop deep for halibut and lingcod.', '{"lat": 50.0331, "lng": -125.2733}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 66, "humidity": 75, "windSpeed": 10, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy trolling rod", "Flashers and hootchies or cut plug herring", "Downrigger", "Rain gear"], "optional": ["Guided charter", "Bait cooler", "Halibut jigging outfit"]}'::jsonb, '["Chinook (Jul-Sep)", "Coho (Sep-Oct)", "Tide changes"]'::jsonb, 'Intermediate', '["DFO Tidal Waters Sport Fishing Licence required (federal, separate from provincial)", "Salmon Conservation Stamp required to keep Pacific salmon", "Area closures and daily limits change in-season — check DFO notices"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-nipissing-walleye', 'Lake Nipissing', 'North Bay, ON', 'CA', 'Freshwater', '["walleye", "northern pike", "smallmouth bass"]'::jsonb, 'fishing-spot', false, 'A big, shallow Ontario lake famous for its walleye and a huge winter ice hut village. Warm water and extensive shoals make it productive from open water right through the hard-water season.', '{"lat": 46.2833, "lng": -79.75}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 75, "humidity": 65, "windSpeed": 12, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-light spin combo", "Jigs and worm harnesses", "Sounder", "Landing net"], "optional": ["Boat rental", "Ice hut booking (winter)", "Portable heater"]}'::jsonb, '["Walleye opener (May)", "Evening bite in summer", "Ice fishing (Jan-Mar)"]'::jsonb, 'Beginner', '["Ontario Outdoors Card and fishing licence required", "Walleye slot size and seasonal closures apply", "Check current Ontario fishing regulations for Zone 11"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('miramichi-atlantic-salmon', 'Miramichi River', 'Miramichi, NB', 'CA', 'Fly Fishing', '["Atlantic salmon", "brook trout"]'::jsonb, 'duck-spot', true, 'North America''s most storied Atlantic salmon river. Swing wet flies through classic named pools for bright fish running from the sea, with brook trout filling the quieter stretches.', '{"lat": 46.9, "lng": -65.85}'::jsonb, '{"current": 20, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Light Rain", "temperature": 68, "humidity": 80, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft 8-weight fly rod", "Bombers and classic wet flies", "Chest waders", "Insect repellent"], "optional": ["Guide or lodge booking", "Wading staff", "Spey rod for bigger pools"]}'::jsonb, '["Summer run (Jun-Jul)", "Autumn run (Sep-Oct)", "After rain lifts the water"]'::jsonb, 'Advanced', '["New Brunswick angling licence plus a separate Atlantic salmon licence and tags required", "Atlantic salmon is largely live release — check current DFO rules", "Non-residents must fish with a licensed guide on many stretches"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-winnipeg-walleye', 'Lake Winnipeg Greenbacks', 'Gimli, MB', 'CA', 'Freshwater', '["walleye", "channel catfish", "northern pike"]'::jsonb, 'fishing-spot', false, 'Home of the ''greenback'' walleye, a distinctly coloured strain that grows to trophy size in this vast, shallow prairie lake. Winter draws anglers onto the ice in large numbers.', '{"lat": 50.5, "lng": -96.8}'::jsonb, '{"current": 20, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 73, "humidity": 60, "windSpeed": 18, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo", "Jigs with plastics", "Warm layers", "Sounder"], "optional": ["Ice fishing gear (winter)", "Boat with reliable motor", "Auger"]}'::jsonb, '["Autumn trophy run (Oct-Nov)", "Ice season (Jan-Mar)", "Spring post-spawn"]'::jsonb, 'Beginner', '["Manitoba angling licence required", "Conservation licence option has reduced limits", "Walleye size and possession limits apply — check Manitoba regulations"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('haida-gwaii-halibut', 'Haida Gwaii', 'Haida Gwaii, BC', 'CA', 'Saltwater', '["halibut", "chinook salmon", "lingcod"]'::jsonb, 'duck-spot', false, 'A remote archipelago off the north coast of British Columbia with some of the richest cold water on the Pacific coast. Big halibut, feeder chinook and lingcod over rugged bottom structure.', '{"lat": 54.0, "lng": -132.0}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Showers", "temperature": 59, "humidity": 85, "windSpeed": 15, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy jigging outfit for halibut", "Salmon trolling gear", "Full rain gear", "Circle hooks"], "optional": ["Fly-in lodge package", "Downriggers", "Marine forecast app"]}'::jsonb, '["Chinook (Jun-Aug)", "Halibut (May-Sep)", "Slack tide for bottom fishing"]'::jsonb, 'Advanced', '["DFO Tidal Waters Sport Fishing Licence required", "Halibut size and annual limits apply; some areas are closed", "Respect Haida Nation protected areas and Gwaii Haanas rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-simcoe-ontario', 'Lake Simcoe', 'Barrie, ON', 'CA', 'Freshwater', '["lake trout", "yellow perch", "whitefish"]'::jsonb, 'fishing-spot', false, 'Ontario''s ice fishing capital, an hour north of Toronto. Deep, clear water holds lake trout and whitefish, while jumbo perch draw crowds of hut anglers every winter.', '{"lat": 44.4167, "lng": -79.35}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 75, "humidity": 60, "windSpeed": 10, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin or jigging rod", "Tube jigs and small spoons", "Sounder or flasher", "Warm layers"], "optional": ["Ice hut rental (winter)", "Boat with downrigger", "Auger and sled"]}'::jsonb, '["Ice season (Jan-Mar)", "Lake trout opener", "Autumn perch schools"]'::jsonb, 'Beginner', '["Ontario Outdoors Card and fishing licence required", "Lake trout season and slot limits apply", "Ice conditions vary — check local reports before going out"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('tobin-lake-saskatchewan', 'Tobin Lake', 'Nipawin, SK', 'CA', 'Freshwater', '["walleye", "northern pike", "yellow perch"]'::jsonb, 'duck-spot', false, 'A Saskatchewan reservoir with a reputation for genuinely giant walleye and pike. Former provincial records have come from here, and the winter fishery is equally productive.', '{"lat": 53.6, "lng": -103.5}'::jsonb, '{"current": 19, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 73, "humidity": 55, "windSpeed": 12, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin combo", "Large jigs and swimbaits", "Steel or heavy fluoro leader for pike", "Sounder"], "optional": ["Boat with electric motor", "Ice fishing setup (winter)", "Large landing cradle"]}'::jsonb, '["Spring post-spawn (Jun)", "Autumn trophy window (Sep-Oct)", "Ice season (Jan-Mar)"]'::jsonb, 'Intermediate', '["Saskatchewan angling licence required", "Trophy waters have special size limits — check current regulations", "Barbless hooks required in Saskatchewan"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('gaspe-salmon-quebec', 'Gaspé Salmon Rivers', 'Gaspé, QC', 'CA', 'Fly Fishing', '["Atlantic salmon", "brook trout"]'::jsonb, 'fishing-spot', false, 'The York, Dartmouth and Saint-Jean rivers run gin-clear through the Gaspé Peninsula, offering sight fishing to resting Atlantic salmon — some of the clearest salmon water anywhere.', '{"lat": 48.85, "lng": -64.5}'::jsonb, '{"current": 16, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 66, "humidity": 70, "windSpeed": 8, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["8-9 weight fly rod", "Bombers and small wets", "Chest waders", "Polarized sunglasses"], "optional": ["ZEC sector reservation", "Guide hire", "Wading staff"]}'::jsonb, '["Peak run (Jun-Jul)", "Early morning in clear water", "After a rise in water"]'::jsonb, 'Advanced', '["Quebec fishing licence plus Atlantic salmon licence required", "Rivers are managed in sectors — daily access is drawn or reserved through the ZEC", "Release rules and quotas vary by river and sector"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('skeena-river-steelhead', 'Skeena River Steelhead', 'Terrace, BC', 'CA', 'Fly Fishing', '["steelhead", "chinook salmon", "coho salmon"]'::jsonb, 'duck-spot', false, 'The Skeena system and its tributaries produce the largest steelhead on earth. Swing flies through big glacial-green runs in autumn for fish that regularly exceed twenty pounds.', '{"lat": 54.9, "lng": -128.6}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 57, "humidity": 80, "windSpeed": 8, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["7-8 weight Spey rod", "Sink tips and intruder patterns", "Chest waders with studs", "Rain gear"], "optional": ["Jet boat or guide", "Wading staff", "Bear spray"]}'::jsonb, '["Steelhead (Sep-Oct)", "Chinook (Jun-Jul)", "Falling water after rain"]'::jsonb, 'Advanced', '["BC freshwater licence plus steelhead conservation surcharge required", "Classified waters licence needed on many tributaries; non-residents may need a guide", "Steelhead are catch-and-release — check BC freshwater synopsis"]'::jsonb);
